Bash(cd "C:/Arcane-Index" && for f in wiki/concepts/*.md; do
  [ "$f" = "wiki/concepts/_index.md" ] && continue
  has_status=$\(grep -c "^status:" "$f" 2>/dev/null || echo 0\)
  has_created=$\(grep -c "^created:" "$f" 2>/dev/null || echo 0\)
  if [ "$has_status" -eq 0 ] || [ "$has_created" -eq 0 ]; then
    updated=$\(grep "^updated:" "$f" | head -1 | sed 's/updated: *//' | tr -d '"'\)
    awk -v hs="$has_status" -v hc="$has_created" -v upd="$updated" '
      BEGIN{cnt=0}
      /^---$/{
        cnt++
        if\(cnt==2\){
          if\(hs+0==0\) print "status: established"
          if\(hc+0==0\) print "created: " upd
        }
      }
      {print}
    ' "$f" > /tmp/_concept_tmp.md && mv /tmp/_concept_tmp.md "$f"
  fi
done && echo "Done")

